head.b:skin:
/*
-----------------------------------------------
Blogger Template: Al Amin Portfolio & 3D Kinetic
Author: Al Amin.
-----------------------------------------------
*/
body {
  background-color: #060d16;
  color: #f4f4f5;
  margin: 0;
  padding: 0;
}

body.script:
//
(function () {
  'use strict';

  // 1. Mobile Navigation Menu & Smooth Scroll
  var mobileToggle = document.getElementById('mobile-menu-toggle');
  var mobileNav = document.getElementById('mobile-site-nav');
  var iconMenu = document.getElementById('icon-menu');
  var iconClose = document.getElementById('icon-close');
  var mobileOpen = false;

  function setMobileMenu(open) {
    mobileOpen = open;
    if (mobileNav) {
      mobileNav.classList.toggle('hidden', !open);
      mobileNav.classList.toggle('flex', open);
    }
    if (mobileToggle) {
      mobileToggle.setAttribute('aria-expanded', open ? 'true' : 'false');
      mobileToggle.setAttribute('aria-label', open ? 'Close navigation menu' : 'Open navigation menu');
    }
    if (iconMenu) iconMenu.classList.toggle('hidden', open);
    if (iconClose) iconClose.classList.toggle('hidden', !open);
  }

  if (mobileToggle) {
    mobileToggle.addEventListener('click', function () {
      setMobileMenu(!mobileOpen);
    });
  }

  var navLinks = document.querySelectorAll('.js-nav-link');
  navLinks.forEach(function (link) {
    link.addEventListener('click', function (e) {
      e.preventDefault();
      var targetId = link.getAttribute('data-target');
      setMobileMenu(false);
      if (targetId) {
        var el = document.getElementById(targetId);
        if (el) el.scrollIntoView({ behavior: 'smooth', block: 'start' });
      }
    });
  });

  // 2. Portrait fallback handler
  var portraitImg = document.getElementById('hero-portrait-img');
  var portraitFallback = document.getElementById('hero-portrait-fallback');
  if (portraitImg && portraitFallback) {
    portraitImg.addEventListener('error', function () {
      portraitImg.style.display = 'none';
      portraitFallback.classList.remove('hidden');
      portraitFallback.classList.add('flex');
    });
  }

  // 3. Spotlight Card Border Glow
  var spotlightCards = document.querySelectorAll('.spotlight-card');
  spotlightCards.forEach(function (card) {
    card.addEventListener('pointermove', function (e) {
      var rect = card.getBoundingClientRect();
      card.style.setProperty('--mx', (e.clientX - rect.left) + 'px');
      card.style.setProperty('--my', (e.clientY - rect.top) + 'px');
      card.style.setProperty('--spot-opacity', '1');
    });
    card.addEventListener('pointerleave', function () {
      card.style.setProperty('--spot-opacity', '0');
    });
  });

  // 4. Magnetic Button Wrap (mouse only)
  var magneticEls = document.querySelectorAll('.magnetic-wrap');
  magneticEls.forEach(function (wrap) {
    var strength = parseFloat(wrap.getAttribute('data-strength') || '0.25');
    wrap.addEventListener('pointermove', function (e) {
      if (e.pointerType !== 'mouse') return;
      var rect = wrap.getBoundingClientRect();
      var dx = (e.clientX - (rect.left + rect.width / 2)) * strength;
      var dy = (e.clientY - (rect.top + rect.height / 2)) * strength;
      wrap.style.transform = 'translate3d(' + dx + 'px, ' + dy + 'px, 0)';
    });
    wrap.addEventListener('pointerleave', function () {
      wrap.style.transform = 'translate3d(0px, 0px, 0)';
    });
  });

  // 5. Kinetic Cursor (Desktop Ring + Dual U-Arcs + 6 Orbiting Colored Bubbles) & Mobile Touch Bursts
  var ORBIT_BUBBLES = [
    { color: '#38BDF8', size: 5, baseAngle: 0, radiusOffset: 22, speedMul: 1.0 },
    { color: '#F59E0B', size: 4.5, baseAngle: (Math.PI * 2) / 6, radiusOffset: 24, speedMul: 1.15 },
    { color: '#A78BFA', size: 5, baseAngle: (Math.PI * 4) / 6, radiusOffset: 21, speedMul: 0.9 },
    { color: '#34D399', size: 4, baseAngle: (Math.PI * 6) / 6, radiusOffset: 25, speedMul: 1.25 },
    { color: '#FB7185', size: 4.5, baseAngle: (Math.PI * 8) / 6, radiusOffset: 22, speedMul: 1.05 },
    { color: '#FDE047', size: 3.5, baseAngle: (Math.PI * 10) / 6, radiusOffset: 24, speedMul: 1.2 }
  ];

  var fineQuery = window.matchMedia('(hover: hover) and (pointer: fine)');
  var rmQuery = window.matchMedia('(prefers-reduced-motion: reduce)');
  var desktopLayer = document.getElementById('desktop-cursor-layer');
  var touchLayer = document.getElementById('touch-burst-layer');
  var outerRing = document.getElementById('cursor-outer-ring');
  var centerDot = document.getElementById('cursor-center-dot');
  var arcGroup = document.getElementById('cursor-arc-group');
  var cursorSvg = document.getElementById('cursor-svg');
  var innerCircle = document.getElementById('cursor-inner-circle');
  var arcAmber = document.getElementById('cursor-arc-amber');
  var arcCyan = document.getElementById('cursor-arc-cyan');
  var rippleEl = document.getElementById('cursor-ripple');
  var bubbleEls = ORBIT_BUBBLES.map(function (_, idx) {
    return document.getElementById('orbit-bubble-' + idx);
  });

  var desktopEnabled = false;
  var reducedMotion = false;
  var cursorRaf = 0;

  function spawnTouchBurst(x, y) {
    if (!touchLayer) return;
    var wrap = document.createElement('div');
    wrap.setAttribute('aria-hidden', 'true');
    wrap.className = 'fixed pointer-events-none z-[9999] -translate-x-1/2 -translate-y-1/2';
    wrap.style.left = x + 'px';
    wrap.style.top = y + 'px';

    var ring = document.createElement('div');
    ring.className = 'h-9 w-9 rounded-full border border-amber-400/70 animate-ping-once';
    wrap.appendChild(ring);

    ORBIT_BUBBLES.forEach(function (b) {
      var dot = document.createElement('span');
      dot.className = 'absolute left-1/2 top-1/2 rounded-full';
      dot.style.width = b.size + 'px';
      dot.style.height = b.size + 'px';
      dot.style.backgroundColor = b.color;
      dot.style.boxShadow = '0 0 8px ' + b.color;
      var tx = Math.cos(b.baseAngle) * 20;
      var ty = Math.sin(b.baseAngle) * 20;
      dot.style.transform = 'translate(-50%, -50%) translate(' + tx + 'px, ' + ty + 'px)';
      wrap.appendChild(dot);
    });

    touchLayer.appendChild(wrap);
    window.setTimeout(function () {
      if (wrap.parentNode) wrap.parentNode.removeChild(wrap);
    }, 650);
  }

  window.addEventListener('pointerdown', function (e) {
    if (desktopEnabled || reducedMotion || e.pointerType === 'mouse') return;
    spawnTouchBurst(e.clientX, e.clientY);
  }, { passive: true });

  var targetX = window.innerWidth / 2;
  var targetY = window.innerHeight / 2;
  var ringX = targetX;
  var ringY = targetY;
  var dotX = targetX;
  var dotY = targetY;
  var prevX = targetX;
  var prevY = targetY;
  var arcAngle = 0;
  var targetAngle = 0;
  var scaleVal = 1;
  var targetScale = 1;
  var orbitClock = 0;
  var isVisible = false;
  var bubblePos = ORBIT_BUBBLES.map(function () { return { x: targetX, y: targetY }; });

  function setCursorVisibility(visible) {
    isVisible = visible;
    if (outerRing) {
      outerRing.classList.toggle('opacity-100', visible);
      outerRing.classList.toggle('opacity-0', !visible);
    }
    if (centerDot) {
      centerDot.classList.toggle('opacity-100', visible);
      centerDot.classList.toggle('opacity-0', !visible);
    }
    bubbleEls.forEach(function (el) {
      if (!el) return;
      el.classList.toggle('opacity-90', visible);
      el.classList.toggle('opacity-0', !visible);
    });
  }

  function setCursorHover(hovering) {
    if (innerCircle) {
      innerCircle.setAttribute('r', hovering ? '13' : '10');
      innerCircle.setAttribute('stroke', hovering ? 'rgba(245, 158, 11, 0.55)' : 'rgba(244, 244, 245, 0.3)');
    }
    if (arcAmber) arcAmber.setAttribute('stroke-width', hovering ? '2' : '1.5');
    if (arcCyan) arcCyan.setAttribute('stroke-width', hovering ? '1.7' : '1.25');
    if (centerDot) {
      centerDot.style.width = hovering ? '3.5px' : '4.5px';
      centerDot.style.height = hovering ? '3.5px' : '4.5px';
      centerDot.style.backgroundColor = hovering ? '#F59E0B' : '#F4F4F5';
    }
  }

  window.addEventListener('pointermove', function (e) {
    if (!desktopEnabled || e.pointerType !== 'mouse') return;
    targetX = e.clientX;
    targetY = e.clientY;
    if (!isVisible) {
      ringX = targetX;
      ringY = targetY;
      dotX = targetX;
      dotY = targetY;
      bubblePos.forEach(function (b) { b.x = targetX; b.y = targetY; });
      setCursorVisibility(true);
    }

    var targetEl = e.target;
    var interactiveEl = targetEl && targetEl.closest ? targetEl.closest('[data-cursor], button, a, input, textarea, select, [role="button"]') : null;
    if (interactiveEl) {
      var customType = interactiveEl.getAttribute('data-cursor');
      if (customType === 'drag') targetScale = 1.35;
      else if (customType === 'card') targetScale = 1.28;
      else targetScale = 1.22;
      setCursorHover(true);
    } else {
      targetScale = 1;
      setCursorHover(false);
    }
  }, { passive: true });

  window.addEventListener('pointerdown', function (e) {
    if (!desktopEnabled || e.pointerType !== 'mouse') return;
    if (cursorSvg) {
      cursorSvg.classList.remove('scale-100');
      cursorSvg.classList.add('scale-85');
    }
    if (rippleEl) {
      rippleEl.style.left = e.clientX + 'px';
      rippleEl.style.top = e.clientY + 'px';
      rippleEl.classList.remove('animate-ping-once');
      void rippleEl.offsetWidth;
      rippleEl.classList.add('animate-ping-once');
    }
  }, { passive: true });

  window.addEventListener('pointerup', function () {
    if (!desktopEnabled || !cursorSvg) return;
    cursorSvg.classList.remove('scale-85');
    cursorSvg.classList.add('scale-100');
  }, { passive: true });

  document.addEventListener('mouseleave', function () {
    if (desktopEnabled) setCursorVisibility(false);
  });

  function cursorTick() {
    if (!desktopEnabled) return;
    var dx = targetX - prevX;
    var dy = targetY - prevY;
    var speed = Math.hypot(dx, dy);

    orbitClock += 0.028 + Math.min(speed * 0.002, 0.04);

    if (speed > 0.6) {
      targetAngle = (Math.atan2(dy, dx) * 180) / Math.PI;
    } else {
      targetAngle += 0.5;
    }

    var angleDiff = ((targetAngle - arcAngle + 540) % 360) - 180;
    arcAngle += angleDiff * 0.16;

    ringX += (targetX - ringX) * 0.18;
    ringY += (targetY - ringY) * 0.18;
    dotX += (targetX - dotX) * 0.5;
    dotY += (targetY - dotY) * 0.5;
    scaleVal += (targetScale - scaleVal) * 0.18;

    var stretch = Math.min(speed * 0.006, 0.16);

    if (outerRing) {
      outerRing.style.transform = 'translate3d(' + ringX + 'px, ' + ringY + 'px, 0) translate(-50%, -50%) scale(' + (scaleVal + stretch) + ', ' + (scaleVal - stretch * 0.3) + ')';
    }
    if (centerDot) {
      centerDot.style.transform = 'translate3d(' + dotX + 'px, ' + dotY + 'px, 0) translate(-50%, -50%)';
    }
    if (arcGroup) {
      arcGroup.style.transform = 'rotate(' + arcAngle + 'deg)';
      arcGroup.style.transformOrigin = '18px 18px';
    }

    for (var i = 0; i < ORBIT_BUBBLES.length; i++) {
      var spec = ORBIT_BUBBLES[i];
      var a = spec.baseAngle + orbitClock * spec.speedMul;
      var r = spec.radiusOffset * scaleVal + Math.sin(orbitClock * 1.8 + i) * 2.5;
      var desiredX = ringX + Math.cos(a) * r;
      var desiredY = ringY + Math.sin(a) * r;

      var followRate = 0.24 - i * 0.015;
      bubblePos[i].x += (desiredX - bubblePos[i].x) * followRate;
      bubblePos[i].y += (desiredY - bubblePos[i].y) * followRate;

      var bEl = bubbleEls[i];
      if (bEl) {
        bEl.style.transform = 'translate3d(' + bubblePos[i].x + 'px, ' + bubblePos[i].y + 'px, 0) translate(-50%, -50%)';
      }
    }

    prevX = targetX;
    prevY = targetY;
    cursorRaf = requestAnimationFrame(cursorTick);
  }

  function updateCursorMode() {
    reducedMotion = rmQuery.matches;
    desktopEnabled = fineQuery.matches && !reducedMotion;
    document.body.classList.toggle('kinetic-cursor-active', desktopEnabled);
    if (desktopLayer) {
      desktopLayer.style.display = desktopEnabled ? 'block' : 'none';
    }
    cancelAnimationFrame(cursorRaf);
    if (desktopEnabled) {
      cursorRaf = requestAnimationFrame(cursorTick);
    }
  }

  updateCursorMode();
  if (fineQuery.addEventListener) fineQuery.addEventListener('change', updateCursorMode);
  if (rmQuery.addEventListener) rmQuery.addEventListener('change', updateCursorMode);

  // 6. Contact Form (FormSubmit AJAX + Dynamic Mailto)
  var ADMIN_EMAIL = 'mdalamin76553@gmail.com';
  var formEl = document.getElementById('contact-form');
  var successEl = document.getElementById('contact-success');
  var nameInput = document.getElementById('visitorName');
  var emailInput = document.getElementById('visitorEmail');
  var businessInput = document.getElementById('businessName');
  var msgInput = document.getElementById('visitorMessage');
  var errEl = document.getElementById('contact-error');
  var warnEl = document.getElementById('contact-warning');
  var warnTextEl = document.getElementById('contact-warning-text');
  var submitBtn = document.getElementById('contact-submit-btn');
  var resetBtn = document.getElementById('contact-reset-btn');
  var successFrom = document.getElementById('success-from');
  var successBiz = document.getElementById('success-business');
  var mailtoLinks = document.querySelectorAll('.js-mailto-link');

  function buildMailtoHref() {
    var n = (nameInput ? nameInput.value : '').trim();
    var em = (emailInput ? emailInput.value : '').trim();
    var bz = (businessInput ? businessInput.value : '').trim();
    var ms = (msgInput ? msgInput.value : '').trim();
    var subject = encodeURIComponent('New Client From Website - ' + (bz || 'Al Amin'));
    var body = encodeURIComponent(
      'Name: ' + n + '\nEmail: ' + em + '\nBusiness Name: ' + bz + '\n\nMessage:\n' + ms
    );
    return 'mailto:' + ADMIN_EMAIL + '?subject=' + subject + '&body=' + body;
  }

  function syncMailtoLinks() {
    var href = buildMailtoHref();
    mailtoLinks.forEach(function (a) {
      a.setAttribute('href', href);
    });
  }

  [nameInput, emailInput, businessInput, msgInput].forEach(function (inp) {
    if (inp) inp.addEventListener('input', syncMailtoLinks);
  });
  syncMailtoLinks();

  if (resetBtn) {
    resetBtn.addEventListener('click', function () {
      if (nameInput) nameInput.value = '';
      if (emailInput) emailInput.value = '';
      if (businessInput) businessInput.value = '';
      if (msgInput) msgInput.value = '';
      if (errEl) errEl.classList.add('hidden');
      if (warnEl) warnEl.classList.add('hidden');
      if (successEl) {
        successEl.classList.add('hidden');
        successEl.classList.remove('flex');
      }
      if (formEl) formEl.classList.remove('hidden');
      syncMailtoLinks();
    });
  }

  if (formEl) {
    formEl.addEventListener('submit', function (e) {
      e.preventDefault();
      var n = (nameInput ? nameInput.value : '').trim();
      var em = (emailInput ? emailInput.value : '').trim();
      var bz = (businessInput ? businessInput.value : '').trim();
      var ms = (msgInput ? msgInput.value : '').trim();

      if (!n || !em || !bz || !ms) {
        if (errEl) {
          errEl.textContent = 'Please fill in your name, email, business name, and message.';
          errEl.classList.remove('hidden');
        }
        return;
      }

      if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(em)) {
        if (errEl) {
          errEl.textContent = 'Please enter a valid email address.';
          errEl.classList.remove('hidden');
        }
        return;
      }

      if (errEl) errEl.classList.add('hidden');
      if (warnEl) warnEl.classList.add('hidden');
      if (submitBtn) {
        submitBtn.disabled = true;
        submitBtn.textContent = 'Sending...';
      }

      fetch('https://formsubmit.co/ajax/' + ADMIN_EMAIL, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Accept': 'application/json'
        },
        body: JSON.stringify({
          _subject: 'New Client From Website - ' + bz,
          _replyto: em,
          _captcha: 'false',
          _template: 'table',
          name: n,
          email: em,
          business: bz,
          message: ms
        })
      })
      .then(function (response) {
        return response.json().catch(function () { return {}; }).then(function (data) {
          return { ok: response.ok, data: data };
        });
      })
      .then(function (res) {
        var isOk = res.ok && (res.data.success === true || res.data.success === 'true');
        if (!isOk) {
          var msg = (res.data && typeof res.data.message === 'string' && res.data.message.trim())
            ? res.data.message
            : 'FormSubmit requires one-time email activation or blocked this browser request.';
          if (warnTextEl) warnTextEl.textContent = msg;
          if (warnEl) warnEl.classList.remove('hidden');
          return;
        }
        if (successFrom) successFrom.textContent = n + ' (' + em + ')';
        if (successBiz) successBiz.textContent = bz;
        formEl.classList.add('hidden');
        if (successEl) {
          successEl.classList.remove('hidden');
          successEl.classList.add('flex');
        }
      })
      .catch(function () {
        if (warnTextEl) {
          warnTextEl.textContent = 'Could not reach FormSubmit automatically from this browser session. Use the direct email button below to send directly to mdalamin76553@gmail.com.';
        }
        if (warnEl) warnEl.classList.remove('hidden');
      })
      .finally(function () {
        if (submitBtn) {
          submitBtn.disabled = false;
          submitBtn.innerHTML = 'Send Message &#8599;';
        }
      });
    });
  }
})();
//

//
import * as THREE from 'https://esm.sh/three@0.187.0';
import { OrbitControls } from 'https://esm.sh/three@0.187.0/examples/jsm/controls/OrbitControls.js';
import { RoomEnvironment } from 'https://esm.sh/three@0.187.0/examples/jsm/environments/RoomEnvironment.js';
import { RectAreaLightUniformsLib } from 'https://esm.sh/three@0.187.0/examples/jsm/lights/RectAreaLightUniformsLib.js';

const heroSection = document.getElementById('home');
const container = document.getElementById('hero-canvas-mount');
const lostOverlay = document.getElementById('webgl-context-lost');

if (container && heroSection) {
  const _vec3 = new THREE.Vector3();
  const _dummy = new THREE.Object3D();
  const _mouseNdc = new THREE.Vector2();
  const _raycaster = new THREE.Raycaster();
  const _cursorPlane = new THREE.Plane(new THREE.Vector3(0, 0, 1), 0);
  const _cursorWorld = new THREE.Vector3(0, 0, 0);
  const _camTargetPos = new THREE.Vector3(0, 0.35, 7.2);
  const _camLookTarget = new THREE.Vector3(0, 0.05, 0);

  function detectSoftwareGl() {
    try {
      const canvas = document.createElement('canvas');
      const gl = canvas.getContext('webgl2') || canvas.getContext('webgl');
      if (!gl) return true;
      const ext = gl.getExtension('WEBGL_debug_renderer_info');
      const param = ext ? ext.UNMASKED_RENDERER_WEBGL : gl.RENDERER;
      const gpu = String(gl.getParameter(param) || '');
      const lose = gl.getExtension('WEBGL_lose_context');
      if (lose) lose.loseContext();
      return /SwiftShader|llvmpipe|softpipe|Software|Basic Render/i.test(gpu);
    } catch (e) {
      return true;
    }
  }

  function createRadialShadowTexture() {
    const size = 256;
    const canvas = document.createElement('canvas');
    canvas.width = size;
    canvas.height = size;
    const ctx = canvas.getContext('2d');
    const grad = ctx.createRadialGradient(size / 2, size / 2, 10, size / 2, size / 2, size / 2);
    grad.addColorStop(0, 'rgba(0, 0, 0, 0.85)');
    grad.addColorStop(0.45, 'rgba(0, 0, 0, 0.38)');
    grad.addColorStop(1, 'rgba(0, 0, 0, 0)');
    ctx.fillStyle = grad;
    ctx.fillRect(0, 0, size, size);
    const tex = new THREE.CanvasTexture(canvas);
    tex.colorSpace = THREE.SRGBColorSpace;
    return tex;
  }

  function createBrushedMetalBumpTexture(maxAniso) {
    const size = 256;
    const canvas = document.createElement('canvas');
    canvas.width = size;
    canvas.height = size;
    const ctx = canvas.getContext('2d');
    ctx.fillStyle = '#808080';
    ctx.fillRect(0, 0, size, size);
    for (let y = 0; y < size; y++) {
      const v = 116 + Math.floor(Math.random() * 24);
      ctx.fillStyle = 'rgb(' + v + ',' + v + ',' + v + ')';
      ctx.fillRect(0, y, size, 1);
    }
    const tex = new THREE.CanvasTexture(canvas);
    tex.wrapS = THREE.RepeatWrapping;
    tex.wrapT = THREE.RepeatWrapping;
    tex.repeat.set(3, 3);
    tex.anisotropy = maxAniso;
    return tex;
  }

  function createFiveStarGeometry(outerR, innerR, depth) {
    const shape = new THREE.Shape();
    const points = 5;
    for (let i = 0; i < points * 2; i++) {
      const r = i % 2 === 0 ? outerR : innerR;
      const angle = (i * Math.PI) / points + Math.PI / 2;
      const x = Math.cos(angle) * r;
      const y = Math.sin(angle) * r;
      if (i === 0) shape.moveTo(x, y);
      else shape.lineTo(x, y);
    }
    shape.closePath();
    const geo = new THREE.ExtrudeGeometry(shape, {
      depth: depth,
      bevelEnabled: true,
      bevelThickness: 0.06,
      bevelSize: 0.045,
      bevelSegments: 3
    });
    geo.center();
    return geo;
  }

  function createBeveledRingGeometry(outerR, innerR, depth) {
    const shape = new THREE.Shape();
    shape.absarc(0, 0, outerR, 0, Math.PI * 2, false);
    const hole = new THREE.Path();
    hole.absarc(0, 0, innerR, 0, Math.PI * 2, true);
    shape.holes.push(hole);
    const geo = new THREE.ExtrudeGeometry(shape, {
      depth: depth,
      bevelEnabled: true,
      bevelThickness: 0.035,
      bevelSize: 0.03,
      bevelSegments: 3,
      curveSegments: 64
    });
    geo.center();
    return geo;
  }

  const isSoftwareGl = detectSoftwareGl();
  const width = Math.max(container.clientWidth, 320);
  const height = Math.max(container.clientHeight, 320);

  const scene = new THREE.Scene();
  scene.background = new THREE.Color(0x060d16);
  scene.fog = new THREE.FogExp2(0x060d16, 0.042);

  const camera = new THREE.PerspectiveCamera(42, width / height, 0.1, 80);
  camera.position.copy(_camTargetPos);

  const renderer = new THREE.WebGLRenderer({
    antialias: !isSoftwareGl,
    powerPreference: 'high-performance'
  });
  renderer.setSize(width, height);
  renderer.setPixelRatio(isSoftwareGl ? 1 : Math.min(window.devicePixelRatio, 2));
  renderer.outputColorSpace = THREE.SRGBColorSpace;
  renderer.toneMapping = THREE.ACESFilmicToneMapping;
  renderer.toneMappingExposure = 1.15;
  renderer.shadowMap.enabled = !isSoftwareGl;
  renderer.shadowMap.type = THREE.PCFSoftShadowMap;
  renderer.domElement.style.display = 'block';
  renderer.domElement.style.width = '100%';
  renderer.domElement.style.height = '100%';
  container.appendChild(renderer.domElement);

  const maxAniso = renderer.capabilities.getMaxAnisotropy();

  const pmremGenerator = new THREE.PMREMGenerator(renderer);
  const roomEnv = new RoomEnvironment();
  const envTex = pmremGenerator.fromScene(roomEnv, 0.04).texture;
  scene.environment = envTex;
  roomEnv.dispose();
  pmremGenerator.dispose();

  const hemiLight = new THREE.HemisphereLight(0xdbeafe, 0x101827, 0.8);
  scene.add(hemiLight);

  const keyLight = new THREE.DirectionalLight(0xffedd5, 2.4);
  keyLight.position.set(5, 7, 5);
  keyLight.castShadow = !isSoftwareGl;
  keyLight.shadow.mapSize.set(1024, 1024);
  keyLight.shadow.camera.left = -5;
  keyLight.shadow.camera.right = 5;
  keyLight.shadow.camera.top = 5;
  keyLight.shadow.camera.bottom = -5;
  keyLight.shadow.camera.near = 1;
  keyLight.shadow.camera.far = 20;
  keyLight.shadow.bias = -0.0005;
  keyLight.shadow.normalBias = 0.02;
  scene.add(keyLight);

  const rimLight = new THREE.DirectionalLight(0xfbbf24, 1.5);
  rimLight.position.set(-5, 3, -5);
  scene.add(rimLight);

  if (!isSoftwareGl) {
    RectAreaLightUniformsLib.init();
    const softbox1 = new THREE.RectAreaLight(0xfff7ed, 4.5, 4, 2);
    softbox1.position.set(4.5, 3.5, 3.5);
    softbox1.lookAt(0, 0, 0);
    scene.add(softbox1);

    const softbox2 = new THREE.RectAreaLight(0xbae6fd, 2.6, 3.5, 2.5);
    softbox2.position.set(-4.5, -1.5, 3);
    softbox2.lookAt(0, 0, 0);
    scene.add(softbox2);
  }

  const isCoarsePointer = window.matchMedia('(pointer: coarse)').matches;
  renderer.domElement.style.touchAction = isCoarsePointer ? 'pan-y' : 'none';

  const controls = new OrbitControls(camera, renderer.domElement);
  controls.enabled = !isCoarsePointer;
  controls.enableDamping = !isSoftwareGl;
  controls.dampingFactor = 0.055;
  controls.enablePan = false;
  controls.enableZoom = !isCoarsePointer;
  controls.minDistance = 4.0;
  controls.maxDistance = 12.0;
  controls.minPolarAngle = 0.35;
  controls.maxPolarAngle = Math.PI - 0.35;
  controls.target.copy(_camLookTarget);

  const shadowTex = createRadialShadowTexture();
  const shadowPlane = new THREE.Mesh(
    new THREE.PlaneGeometry(6.5, 6.5),
    new THREE.MeshBasicMaterial({
      map: shadowTex,
      transparent: true,
      depthWrite: false,
      opacity: 0.68
    })
  );
  shadowPlane.rotation.x = -Math.PI / 2;
  shadowPlane.position.y = -2.42;
  scene.add(shadowPlane);

  const stagePlinth = new THREE.Mesh(
    new THREE.RingGeometry(1.78, 1.81, 72),
    new THREE.MeshBasicMaterial({
      color: 0xf59e0b,
      transparent: true,
      opacity: 0.18,
      side: THREE.DoubleSide,
      depthWrite: false,
      polygonOffset: true,
      polygonOffsetFactor: -1,
      polygonOffsetUnits: -1
    })
  );
  stagePlinth.rotation.x = -Math.PI / 2;
  stagePlinth.position.y = -2.4;
  scene.add(stagePlinth);

  const brushedBump = createBrushedMetalBumpTexture(maxAniso);

  const primaryMat = new THREE.MeshPhysicalMaterial({
    color: 0xf59e0b,
    metalness: 0.95,
    roughness: 0.16,
    bumpMap: brushedBump,
    bumpScale: 0.008,
    anisotropy: 0.75,
    anisotropyRotation: 0.25,
    clearcoat: 0.25,
    clearcoatRoughness: 0.15
  });

  const secondaryMat = new THREE.MeshStandardMaterial({
    color: 0x162235,
    metalness: 0.55,
    roughness: 0.48
  });

  const crystalMat = new THREE.MeshPhysicalMaterial({
    color: 0xfef3c7,
    metalness: 0.05,
    roughness: 0.08,
    transmission: isSoftwareGl ? 0 : 0.88,
    transparent: true,
    opacity: isSoftwareGl ? 0.52 : 1.0,
    ior: 1.65,
    thickness: 1.2,
    clearcoat: 1.0,
    clearcoatRoughness: 0.05,
    iridescence: 0.45,
    depthWrite: !isSoftwareGl
  });

  const filamentMat = new THREE.MeshStandardMaterial({
    color: 0xfbbf24,
    emissive: 0xf59e0b,
    emissiveIntensity: 1.45,
    roughness: 0.22,
    metalness: 0.2
  });

  const rootRig = new THREE.Group();
  rootRig.position.y = 0.05;
  scene.add(rootRig);

  const starGroup = new THREE.Group();
  rootRig.add(starGroup);

  const mainStarGeo = createFiveStarGeometry(0.76, 0.34, 0.22);
  const mainStarMesh = new THREE.Mesh(mainStarGeo, filamentMat);
  mainStarMesh.castShadow = !isSoftwareGl;
  starGroup.add(mainStarMesh);

  const crystalShellMesh = new THREE.Mesh(new THREE.IcosahedronGeometry(0.92, 1), crystalMat);
  crystalShellMesh.renderOrder = 2;
  starGroup.add(crystalShellMesh);

  const outerRingMesh = new THREE.Mesh(createBeveledRingGeometry(1.78, 1.58, 0.14), primaryMat);
  outerRingMesh.castShadow = !isSoftwareGl;
  starGroup.add(outerRingMesh);

  const midRingMesh = new THREE.Mesh(createBeveledRingGeometry(1.42, 1.25, 0.12), secondaryMat);
  midRingMesh.castShadow = !isSoftwareGl;
  starGroup.add(midRingMesh);

  const innerRingMesh = new THREE.Mesh(new THREE.TorusGeometry(1.06, 0.045, 18, 72), primaryMat);
  starGroup.add(innerRingMesh);

  const miniStarGeo = createFiveStarGeometry(0.2, 0.09, 0.07);
  const satStars = [];
  for (let i = 0; i < 5; i++) {
    const sat = new THREE.Mesh(miniStarGeo, primaryMat);
    sat.castShadow = !isSoftwareGl;
    sat.userData.baseAngle = (i / 5) * Math.PI * 2;
    starGroup.add(sat);
    satStars.push(sat);
  }

  const pinGeo = new THREE.CylinderGeometry(0.025, 0.025, 0.22, 10);
  pinGeo.rotateX(Math.PI / 2);
  const pinCount = 30;
  const pinInstanced = new THREE.InstancedMesh(pinGeo, filamentMat, pinCount);
  for (let i = 0; i < pinCount; i++) {
    const a = (i / pinCount) * Math.PI * 2;
    _dummy.position.set(Math.cos(a) * 1.68, Math.sin(a) * 1.68, 0);
    _dummy.rotation.set(0, 0, a);
    _dummy.scale.setScalar(1);
    _dummy.updateMatrix();
    pinInstanced.setMatrixAt(i, _dummy.matrix);
  }
  pinInstanced.instanceMatrix.needsUpdate = true;
  pinInstanced.computeBoundingSphere();
  outerRingMesh.add(pinInstanced);

  // Orbital Stardust (160 shards)
  const shardCount = 160;
  const shardInstanced = new THREE.InstancedMesh(
    new THREE.OctahedronGeometry(0.032, 0),
    new THREE.MeshStandardMaterial({ color: 0xffffff, metalness: 0.7, roughness: 0.25 }),
    shardCount
  );
  shardInstanced.frustumCulled = false;

  const shardData = Array.from({ length: shardCount }, (_, i) => ({
    angle: (i / shardCount) * Math.PI * 2 + Math.random() * 0.4,
    radius: 2.15 + Math.random() * 2.1,
    yOffset: (Math.random() - 0.5) * 2.8,
    speed: 0.18 + Math.random() * 0.35,
    scale: 0.65 + Math.random() * 0.85,
    phase: Math.random() * Math.PI * 2
  }));

  const tintColors = [0xf59e0b, 0xfef3c7, 0xcbd5e1, 0x38bdf8];
  const _color = new THREE.Color();
  for (let i = 0; i < shardCount; i++) {
    _color.setHex(tintColors[i % tintColors.length]);
    shardInstanced.setColorAt(i, _color);
  }
  if (shardInstanced.instanceColor) shardInstanced.instanceColor.needsUpdate = true;
  scene.add(shardInstanced);

  // Compact 3D Cursor Halo Ring
  const cursorHaloGroup = new THREE.Group();
  const haloRing = new THREE.Mesh(
    new THREE.RingGeometry(0.15, 0.17, 48),
    new THREE.MeshBasicMaterial({
      color: 0xf59e0b,
      transparent: true,
      opacity: 0.5,
      side: THREE.DoubleSide,
      depthWrite: false
    })
  );
  const haloArc = new THREE.Mesh(
    new THREE.RingGeometry(0.21, 0.23, 48, 1, 0, Math.PI * 0.85),
    new THREE.MeshBasicMaterial({
      color: 0x38bdf8,
      transparent: true,
      opacity: 0.55,
      side: THREE.DoubleSide,
      depthWrite: false
    })
  );
  cursorHaloGroup.add(haloRing, haloArc);
  cursorHaloGroup.position.set(0, 0, 1.4);
  cursorHaloGroup.visible = false;
  scene.add(cursorHaloGroup);

  let pointerActive = false;
  let pointerNx = 0;
  let pointerNy = 0;
  let smoothPointerX = 0;
  let smoothPointerY = 0;
  const explodeVal = 0.15;

  function updatePointerFromClient(clientX, clientY) {
    const rect = heroSection.getBoundingClientRect();
    pointerNx = ((clientX - rect.left) / rect.width) * 2 - 1;
    pointerNy = -((clientY - rect.top) / rect.height) * 2 + 1;
    pointerActive = true;
  }

  heroSection.addEventListener('pointermove', (e) => {
    updatePointerFromClient(e.clientX, e.clientY);
  }, { passive: true });

  heroSection.addEventListener('pointerleave', () => {
    pointerNx = 0;
    pointerNy = 0;
    pointerActive = false;
  });

  heroSection.addEventListener('touchmove', (e) => {
    if (e.touches && e.touches.length > 0) {
      updatePointerFromClient(e.touches[0].clientX, e.touches[0].clientY);
    }
  }, { passive: true });

  heroSection.addEventListener('touchend', () => {
    pointerNx = 0;
    pointerNy = 0;
    pointerActive = false;
  });

  renderer.domElement.addEventListener('webglcontextlost', (e) => {
    e.preventDefault();
    if (lostOverlay) { lostOverlay.classList.remove('hidden'); lostOverlay.classList.add('flex'); }
  });
  renderer.domElement.addEventListener('webglcontextrestored', () => {
    if (lostOverlay) { lostOverlay.classList.add('hidden'); lostOverlay.classList.remove('flex'); }
  });

  if (!isSoftwareGl) {
    renderer.compile(scene, camera);
  }

  const handleResize = () => {
    const w = Math.max(container.clientWidth, 320);
    const h = Math.max(container.clientHeight, 320);
    camera.aspect = w / h;
    camera.updateProjectionMatrix();
    renderer.setSize(w, h);
  };
  const resizeObserver = new ResizeObserver(handleResize);
  resizeObserver.observe(container);

  const clock = new THREE.Clock();

  function afterDraw(cb) {
    const gl = renderer.getContext();
    if (gl && typeof gl.fenceSync === 'function') {
      const sync = gl.fenceSync(gl.SYNC_GPU_COMMANDS_COMPLETE, 0);
      gl.flush();
      const poll = () => {
        const state = sync && gl.getSyncParameter(sync, gl.SYNC_STATUS);
        if (state === gl.UNSIGNALED) {
          window.setTimeout(poll, 5);
        } else {
          if (sync) gl.deleteSync(sync);
          window.setTimeout(cb, 80);
        }
      };
      window.setTimeout(poll, 5);
    } else {
      window.setTimeout(cb, 80);
    }
  }

  function tick() {
    const delta = Math.min(clock.getDelta(), 0.05);
    const elapsed = clock.getElapsedTime();

    const targetPx = pointerActive ? pointerNx : Math.sin(elapsed * 0.4) * 0.15;
    const targetPy = pointerActive ? pointerNy : Math.cos(elapsed * 0.3) * 0.1;
    smoothPointerX = THREE.MathUtils.damp(smoothPointerX, targetPx, 6, delta);
    smoothPointerY = THREE.MathUtils.damp(smoothPointerY, targetPy, 6, delta);

    rootRig.rotation.y = THREE.MathUtils.damp(rootRig.rotation.y, smoothPointerX * 0.35, 5, delta);
    rootRig.rotation.x = THREE.MathUtils.damp(rootRig.rotation.x, -smoothPointerY * 0.25, 5, delta);

    if (pointerActive) {
      cursorHaloGroup.visible = true;
      _mouseNdc.set(pointerNx, pointerNy);
      _raycaster.setFromCamera(_mouseNdc, camera);
      _cursorPlane.normal.copy(camera.position).normalize();
      _cursorPlane.constant = -1.6;
      if (_raycaster.ray.intersectPlane(_cursorPlane, _cursorWorld)) {
        cursorHaloGroup.position.lerp(_cursorWorld, 1 - Math.exp(-12 * delta));
        cursorHaloGroup.lookAt(camera.position);
        haloArc.rotation.z = elapsed * 2.4;
      }
    } else {
      cursorHaloGroup.visible = false;
    }

    rootRig.position.y = 0.05 + Math.sin(elapsed * 1.4) * 0.08;

    mainStarMesh.rotation.y = elapsed * 0.65;
    crystalShellMesh.rotation.y = -elapsed * 0.35;
    crystalShellMesh.rotation.x = elapsed * 0.2;

    outerRingMesh.rotation.x = Math.sin(elapsed * 0.55) * 0.45;
    outerRingMesh.rotation.y = elapsed * 0.35;
    outerRingMesh.position.z = explodeVal * 0.65;

    midRingMesh.rotation.y = -elapsed * 0.6;
    midRingMesh.rotation.z = Math.cos(elapsed * 0.45) * 0.65;
    midRingMesh.position.z = -explodeVal * 0.55;

    innerRingMesh.rotation.x = elapsed * 0.9;
    innerRingMesh.rotation.z = elapsed * 0.45;

    const satRadius = 1.24 + explodeVal * 0.9;
    for (let i = 0; i < satStars.length; i++) {
      const sat = satStars[i];
      const a = sat.userData.baseAngle + elapsed * 0.45;
      sat.position.set(
        Math.cos(a) * satRadius,
        Math.sin(a) * satRadius,
        Math.cos(elapsed * 1.2 + i) * (0.28 + explodeVal * 0.35)
      );
      sat.rotation.y = elapsed * 1.1;
      sat.rotation.z = a;
    }

    for (let i = 0; i < shardCount; i++) {
      const s = shardData[i];
      const a = s.angle + elapsed * s.speed;
      const r = s.radius + explodeVal * 0.75;
      _vec3.set(
        Math.cos(a) * r + smoothPointerX * 0.45,
        s.yOffset + Math.sin(elapsed * 1.1 + s.phase) * 0.25 + smoothPointerY * 0.35,
        Math.sin(a) * r
      );
      _dummy.position.copy(_vec3);
      _dummy.rotation.set(elapsed + s.phase, elapsed * 0.7, s.phase);
      _dummy.scale.setScalar(s.scale);
      _dummy.updateMatrix();
      shardInstanced.setMatrixAt(i, _dummy.matrix);
    }
    shardInstanced.instanceMatrix.needsUpdate = true;

    controls.update();
    renderer.render(scene, camera);

    if (isSoftwareGl) afterDraw(tick);
    else requestAnimationFrame(tick);
  }

  tick();
}
//
